"""Local MQTT broker model; all client credentials/topics are generated by PLC C++ fixture."""
import socket,threading,subprocess,json,argparse
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--work',type=Path,required=True);w=p.parse_args().work
listener=socket.socket();listener.bind(('127.0.0.1',0));listener.listen(1);listener.settimeout(15)
result={};errors=[]
def exact(s,n):
 b=b''
 while len(b)<n:
  part=s.recv(n-len(b));assert part;b+=part
 return b
def packet(s):
 kind=exact(s,1)[0];n=0;shift=0
 while True:
  b=exact(s,1)[0];n+=(b&127)<<shift;shift+=7;assert shift<=28
  if not b&128:break
 assert n<1024
 return kind,exact(s,n)
def field(b,at):
 n=int.from_bytes(b[at:at+2],'big');return b[at+2:at+2+n],at+2+n
def broker():
 try:
  with listener.accept()[0] as s:
   s.settimeout(15);kind,b=packet(s);assert kind==16
   protocol,at=field(b,0);assert protocol==b'MQTT' and b[at:at+4]==bytes([4,0xc2,0,30]);at+=4
   client,at=field(b,at);user,at=field(b,at);password,at=field(b,at);assert client==b'PLC-client' and user==b'plc-user' and password==b'test-only-password' and at==len(b)
   s.sendall(bytes.fromhex('20020000'));kind,b=packet(s);assert kind==0x82 and b[:2]==bytes([0,7]);topic,at=field(b,2);assert topic==b'plc/command' and b[at:]==b'\0';s.sendall(bytes.fromhex('9003000700'))
   kind,b=packet(s);topic,at=field(b,0);assert kind==0x30 and topic==b'plc/value' and b[at:]==b'A'*400
   payload=b'\0\x0bplc/commandon!!!';s.sendall(bytes([0x30,len(payload)])+payload)

   try:assert s.recv(1)==b''
   except ConnectionResetError:pass
   result.update(connect_auth=True,subscribe=True,publish_400=True,incoming=True,close=True,credentials_in_plc_only=True)
 except BaseException as e:errors.append(repr(e))
t=threading.Thread(target=broker,daemon=True);t.start()
run=subprocess.run([str(w/'tcp_proxy_mqtt_native.exe'),'localhost',str(listener.getsockname()[1])],capture_output=True,timeout=35);t.join(5);listener.close();assert run.returncode==0,(run.stdout,run.stderr,errors);assert not errors and result and not t.is_alive(),errors
(w/'MQTT_CHECKS.json').write_text(json.dumps(result,indent=2),encoding='utf-8');print(run.stdout.decode());print(json.dumps(result))
